class TmnxLdpKeepAliveFactor(TextualConvention, Unsigned32):
    description = 'TmnxLdpKeepAliveFactor specifies the value by which the keepalive\n         timeout should be divided to give the keepalive time i.e. the time\n         interval, in seconds, between LDP Keepalive messages. LDP Keepalive\n         messages are sent to keep the LDP session from timing out when no\n         other LDP traffic is being sent between the neighbors.'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(1, 255)

class TmnxLdpKeepAliveTimeout(TextualConvention, Unsigned32):
    description = 'TmnxLdpKeepAliveTimeout specifies the the time interval, in seconds,\n         that LDP waits before tearing down a session. If no LDP messages are\n         exchanged during this time interval, the LDP session is torn down.\n         Generally the keepalive timeout interval should be configured to be 3\n         times the keepalive time (the time interval between successive LDP\n         Keepalive messages).'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(1, 65535)

class TmnxLdpHelloFactor(TextualConvention, Unsigned32):
    description = 'TmnxLdpHelloFactor specifies the value by which the hello timeout\n         should be divided to give the hello time i.e. the time interval, in\n         seconds, between LDP Hello messages. LDP uses Hello messages to\n         discover neighbors and to detect loss of connectivity with its\n         neighbors.'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(1, 255)

class TmnxLdpHelloTimeout(TextualConvention, Unsigned32):
    description = 'TmnxLdpHelloTimeout specifies the the time interval, in seconds, that\n         LDP waits before declaring a neighbor to be down. Hello timeout is\n         local to the system and is sent in the Hello messages to a neighbor.\n         Hello timeout cannot be set to a value that is less than 3 times the\n         hello time.'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(1, 65535)

class TmnxLdpBackoffTime(TextualConvention, Unsigned32):
    description = 'TmnxLdpBackoffTime specifies the backoff interval (initial and\n         maximum). The backoff interval is the time, in seconds, that LDP waits\n         after an LDP session setup has failed before it attempts to setup the\n         session again. After the LDP session startup fails the first time, the\n         backoff interval is set to an initial value. Thereafter, if session\n         startup fails again the backoff interval increases exponentially until\n         it reaches a maximum value specified by the maximum backoff interval.\n         If the maximum backoff interval is set to zero (0), then the backoff\n         interval does not increase exponentially after the first session\n         startup attempt fails. Instead it remains constant and LDP will keep\n         retrying to establish a session until it succeeds.'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(0, 2592000)

class TmnxLdpFECPolicy(TextualConvention, Integer32):
    description = "TmnxLdpFECPolicy determines whether the LSR should generate FECs and\n         which FECs it should generate.\n\n         system(1) - LDP will distribute label bindings only for the router's\n         system IP address\n\n         interface(2) - LDP will distribute label bindings for all LDP\n         interfaces\n\n         all(3) - LDP will distribute label bindings for all prefixes in the\n         routing table\n\n         none(4) - LDP will not distribute any label bindings."
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))
    namedValues = NamedValues(("system", 1), ("interface", 2), ("all", 3), ("none", 4))

class TmnxLdpLabelDistMethod(TextualConvention, Integer32):
    description = "TmnxLdpLabelDistMethod describes the label distribution method used.\n\n         When the value is 'downstreamOnDemand', label bindings are distributed\n         to the upstream LSR only when a label request message is received.\n\n         When the value is 'downstreamUnsolicited', label bindings are\n         distributed to the upstream LSR, for each FEC, without requiring a\n         request message for the FEC from the upstream LSR."
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2))
    namedValues = NamedValues(("downstreamOnDemand", 1), ("downstreamUnsolicited", 2))

class TmnxLdpAdjacencyType(TextualConvention, Integer32):
    description = 'TmnxLdpAdjacencyType describes the type of adjacency, either targeted\n         or link, for a row in the vRtrLdpHelloAdjTable. It also describes the\n         type of adjacencies in an LDP Session row in the vRtrLdpSessionTable.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3))
    namedValues = NamedValues(("link", 1), ("targeted", 2), ("both", 3))

class TmnxVpnId(TextualConvention, OctetString):
    description = "TmnxVpnId specifies the value of a VPN (Virtual Private Network)\n         identifier. This is a 10 byte value - the VPN 'type' is stored in the\n         first two bytes the TmnxVpnId. The next four bytes store an 'AS\n         (Autonomous System) number'. A 'local identifier' for the VPN is\n         stored as the last four bytes."
    status = 'current'
    subtypeSpec = OctetString.subtypeSpec + ValueSizeConstraint(10, 10)
    fixedLength = 10

class TmnxLabelStatus(TextualConvention, Bits):
    description = "TmnxLabelStatus bit flags specifies the status of an ingress or egress\n         label.\n\n         Flags marked dummy* are not used and MUST be 0.\n\n         'statusSignalingSupported' - indicates whether status signaling is\n                       enabled or not.\n         'inUsePush' - indicates that the label contains valid information\n                       that is currently being used as a 'push' label.\n         'inUseSwap' - indicates that the label contains valid information\n                       that is currently being used as a 'swap' label.\n         'inUsePop'  - indicates that the label contains valid information\n                       that is currently being used as a 'pop' label.\n         'released'  - indicates that the label is in the process of being\n                       freed. With this flag set, no other flags will be set.\n         'notInUse'  - indicates that the label contains valid information\n                       but is currently not being used possibly because the\n                       service is temporarily down.\n         'withdrawn' - indicates that the label has not been sent (possibly\n                       due to a mismatch in control word or status signaling)\n         'controlWord' - indicates that the control word will be signaled\n         'withdrawPending' - indicates that the label withdrawal is pending\n         'alternateNextHop' - indicates that the label is programmed as\n                              alternate next-hop for fast reroute\n         'alternatePHop' - indicates that the label is programmed as alternate\n                           upstream for fast reroute.\n         'unnumIf'   - indicates that the label is programmed using unnumbered\n                       interface.\n         'srIsisNextHop' - LDP binding is resolved to ISIS segment routing\n                           next-hop.\n         'srOspfNextHop' - LDP binding is resolved to OSPF segment routing\n                           next-hop.\n         'entLblCap' - entropy label capabilities.\n         }"
    status = 'current'
    namedValues = NamedValues(("dummyB0", 0), ("dummyB1", 1), ("statusSignalingSupported", 2), ("inUsePush", 3), ("inUseSwap", 4), ("inUsePop", 5), ("released", 6), ("notInUse", 7), ("withdrawn", 8), ("controlWord", 9), ("withdrawPending", 10), ("alternateNextHop", 11), ("alternatePHop", 12), ("unnumIf", 13), ("srIsisNextHop", 14), ("srOspfNextHop", 15), ("entLblCap", 16))

