class TmnxLdpFECFlags(TextualConvention, Bits):
    description = "TmnxLdpFECFlags bit flags define the characteristics of FEC. Flags\n         marked dummy* are not used and MUST be 0.\n\n         Flag 'egress':  this node is an egress for this FEC.\n         Flag 'ingress': this node is a potential ingress for this FEC.\n         Flag 'installedSwap': the label for this FEC has been programmed\n                               as a 'swap' label.\n         Flag 'installedPush': the label for this FEC has been programmed\n                               as a 'push' label.\n         Flag 'installedPop':  the label for this FEC has been programmed\n                               as a 'pop' label.\n         Flag 'local':   this FEC is local to this node.\n         Flag 'nextHop': the nextHop for this FEC is known.\n         Flag 'importPolicyRejected': global LDP import policy has rejected\n                                      this FEC.\n         Flag 'exportPolicyAccepted': global LDP export policy has accepted\n                                      this FEC.\n         Flag 'installedStaticFec': this FEC is created by static FEC\n                                    configuration on this node.\n         Flag 'vcSwitching': vcSwitching is enabled for the FEC.\n         Flag 'importTargPolicyRejected': targeted LDP import policy has\n                                          rejected this FEC.\n         Flag 'exportTargPolicyRejected': targeted LDP export policy has\n                                          rejected this FEC.\n         Flag 'importPeerPolicyRejected': peer LDP import policy has\n                                          rejected this FEC.\n         Flag 'localMultihomedSecondary': this FEC is local to this node\n                                          and is a multi-homed secondary\n                                          ip address.\n         Flag 'bgpNextHop' : LDP binding is resolved to BGP next-hop.\n         Flag 'labelReqSent' : Label request to peer has been sent.\n         Flag 'classBasedForwarding' : Label binding is using\n                                       class-based-forwarding.\n         Flag 'srIsisNextHop' : LDP binding is resolved to ISIS segment routing\n                                next-hop.\n         Flag 'srOspfNextHop' : LDP binding is resolved to OSPF segment routing\n                                next-hop.\n         Flag 'upperFec' : this upper FEC is stitched to lower FEC\n         Flag 'lowerFec' : this lower FEC is stitched to upper FEC\n         Flag 'communityMismatch' : targeted LDP community mismatch\n         Flag 'bkpUpperFec' : backup upper FEC"
    status = 'current'
    namedValues = NamedValues(("dummyB0", 0), ("egress", 1), ("ingress", 2), ("installedSwap", 3), ("installedPush", 4), ("installedPop", 5), ("local", 6), ("nextHop", 7), ("importPolicyRejected", 8), ("exportPolicyAccepted", 9), ("installedStaticFec", 10), ("vcSwitching", 11), ("importTargPolicyRejected", 12), ("exportTargPolicyRejected", 13), ("importPeerPolicyRejected", 14), ("localMultihomedSecondary", 15), ("bgpNextHop", 16), ("labelReqSent", 17), ("classBasedForwarding", 18), ("srIsisNextHop", 19), ("srOspfNextHop", 20), ("upperFec", 21), ("lowerFec", 22), ("communityMismatch", 23), ("bkpUpperFec", 24))

