class TmnxLdpNewKeepAliveTimeout(TextualConvention, Unsigned32):
    description = 'TmnxLdpNewKeepAliveTimeout specifies the the time interval, in\n         seconds, that LDP waits before tearing down a session. If no LDP\n         messages are exchanged during this time interval, the LDP session is\n         torn down. Generally the keepalive timeout interval should be\n         configured to be 3 times the keepalive time (the time interval between\n         successive LDP Keepalive messages).\n\n         The minimum value TmnxLdpKeepAliveTimeout can have is 1 whereas the\n         minimum value TmnxLdpNewKeepAliveTimeout can have is 3. This new\n         textual convention prevents setting value for timeouts to be less than\n         3 seconds.'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(3, 65535)

class TmnxLdpNewHelloTimeout(TextualConvention, Unsigned32):
    description = 'TmnxLdpNewHelloTimeout specifies the the time interval, in seconds,\n         that LDP waits before declaring a neighbor to be down. Hello timeout\n         is local to the system and is sent in the Hello messages to a\n         neighbor. Hello timeout cannot be set to a value that is less than 3\n         times the hello time.\n\n         The minimum value TmnxLdpHelloTimeout can have is 1 whereas the\n         minimum value TmnxLdpNewHelloTimeout can have is 3. This new textual\n         convention prevents setting value for timeouts to be less than 3\n         seconds.'
    status = 'current'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(3, 65535)

class TmnxLdpInLblWdrawalReasonCode(TextualConvention, Integer32):
    description = "TmnxLdpInLblWdrawalReasonCode is an enumerated integer that specifies\n         the reason that the LDP ingress label is withdrawn.\n\n         The value of 'none(0)' means no reason specified for the withdrawal of\n         the ingress label.\n\n         The value of 'noSwLabel(1)' means the ingress label is withdrawn\n         because there is no vc switching label from upstream.\n\n         The value of 'localFault(2)' means the ingress label is withdrawn\n         because there is a local fault.\n\n         The value of 'stackMismatch(3)' means the ingress label is withdrawn\n         due to stack capability mismatch."
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(0, 1, 2, 3))
    namedValues = NamedValues(("none", 0), ("noSwLabel", 1), ("localFault", 2), ("stackMismatch", 3))

