vRtrLdpGenKeepAliveFactor = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 7), TmnxLdpKeepAliveFactor().clone(3)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenKeepAliveFactor.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenKeepAliveFactor.setDescription('The value of vRtrLdpGenKeepAliveFactor specifies the value by which\n         the keepalive timeout (vRtrLdpGenKeepAliveTimeout) should be divided\n         to give the keepalive time i.e. the time interval, in seconds, between\n         LDP keepalive messages. LDP keepalive messages are sent to keep the\n         LDP session from timing out when no other LDP traffic is being sent\n         between the neighbors.\n\n         This value is only applicable to LDP interfaces and not for targeted\n         sessions.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenKeepAliveTimeout = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 8), TmnxLdpNewKeepAliveTimeout().clone(30)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenKeepAliveTimeout.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenKeepAliveTimeout.setDescription('The value of vRtrLdpGenKeepAliveTimeout specifies the time interval,\n         in seconds, that LDP waits before tearing down a session. If no LDP\n         messages are exchanged during this time interval, the LDP session is\n         torn down. Generally the value of vRtrLdpGenKeepAliveTimeout is\n         configured to be 3 times the keepalive time (the time interval between\n         successive LDP keepalive messages).\n\n         This value is only applicable to LDP interfaces and not for targeted\n         sessions.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenHelloFactor = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 9), TmnxLdpHelloFactor().clone(3)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenHelloFactor.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenHelloFactor.setDescription('The value of vRtrLdpGenHelloFactor specifies the value by which the\n         hello timeout (vRtrLdpGenHelloTimeout) should be divided to give the\n         hello time i.e. the time interval, in seconds, between LDP Hello\n         messages. LDP uses hello messages to discover neighbors and to detect\n         loss of connectivity with its neighbors.\n\n         This value is only applicable to LDP interfaces and not for targeted\n         sessions.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenHelloTimeout = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 10), TmnxLdpNewHelloTimeout().clone(15)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenHelloTimeout.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenHelloTimeout.setDescription('The value of vRtrLdpGenHelloTimeout specifies the hello time also\n         known as hold time. It is the time interval, in seconds, that LDP\n         waits before declaring a neighbor to be down. Hello timeout is local\n         to the system and is sent in the hello messages to a neighbor. Hello\n         timeout cannot be set to a value that is less than 3 times the hello\n         time.\n\n         This value is only applicable to LDP interfaces and not for targeted\n         sessions.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenRoutePreference = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 11), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(1, 255)).clone(9)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenRoutePreference.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenRoutePreference.setDescription('The value of vRtrLdpGenRoutePreference specifies the route preference\n         assigned to LDP routes. When multiple routes are available to a\n         destination, the route with the lowest preference will be used.\n\n         This value is only applicable to LDP interfaces and not for targeted\n         sessions.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenControlMode = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 12), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("ordered", 1), ("independent", 2)))).setMaxAccess("readonly")
if mibBuilder.loadTexts: vRtrLdpGenControlMode.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenControlMode.setDescription("The value of vRtrLdpGenControlMode specifies the mode used for\n         distributing labels in response to label binding requests.\n\n         When vRtrLdpGenControlMode has a value of 'ordered', label bindings\n         are not distributed in response to a label request until a label\n         binding has been received from the next hop for the destination.\n\n         When vRtrLdpGenControlMode has a value of 'independent', label\n         bindings are distributed immediately in response to a label request\n         even if a label binding has not yet been received from the next hop\n         for the destination.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenDistMethod = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 13), TmnxLdpLabelDistMethod()).setMaxAccess("readonly")
if mibBuilder.loadTexts: vRtrLdpGenDistMethod.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenDistMethod.setDescription("The value of vRtrLdpGenDistMethod specifies the label distribution\n         method used.\n\n         When vRtrLdpGenDistMethod has a value of 'downstreamOnDemand', label\n         bindings are distributed to the upstream LSR, for each FEC, without\n         requiring a request message for the FEC from the upstream LSR.\n\n         When vRtrLdpGenDistMethod has a value of 'downstreamUnsolicited',\n         label bindings are distributed to the upstream LSR only when a label\n         request message is received.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenRetentionMode = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 14), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("conservative", 1), ("liberal", 2)))).setMaxAccess("readonly")
if mibBuilder.loadTexts: vRtrLdpGenRetentionMode.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenRetentionMode.setDescription("The value of vRtrLdpGenRetentionMode specifies the label retention\n         mode used.\n\n         If the value of this object is 'conservative', then advertised\n         label mappings are retained only if they will be used to forward\n         packets, i.e. if the label came from a valid next hop.  Label\n         bindings received from non-nexthops for each FEC are discarded.\n\n         If the value of this object is 'liberal', then all advertised\n         label mappings are retained whether they are from a valid next\n         hop or not.  When vRtrLdpGenDistMethod has a value of\n         'downstreamUnsolicited', a LSR may receive label bindings for\n         the same destination for all its neighbors.  Labels for the\n         non-nexthops for the FECs are retained in the software but not\n         used.  When a network topology change occurs where a non-nexthop\n         becomes a true next hop, the label received earlier is then used.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenTransportAddrType = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 15), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("interface", 1), ("system", 2))).clone('system')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenTransportAddrType.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenTransportAddrType.setDescription("The value of vRtrLdpGenTransportAddrType specifies the source\n         of the transport address to be used when setting up the LDP TCP\n         sessions.  The transport address can be configured globally\n         (applied to all interfaces) or per interface.\n\n         When the value of this object is 'interface', the interface's IP\n         address is used to setup the LDP session between neighbors. If\n         multiple interfaces exist between two neighbors, the 'interface' mode\n         cannot be used since only one LDP session is actually set up between\n         the two neighbors.\n\n         When the value of this object is 'system', the system's IP address is\n         used to set up the LDP session between neighbors.\n\n         This value is only applicable to LDP interfaces and not for targeted\n         sessions.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenPropagatePolicy = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 16), TmnxLdpFECPolicy().clone('system')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenPropagatePolicy.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenPropagatePolicy.setDescription("The value of vRtrLdpGenPropagatePolicy determines whether the LSR\n         should generate FECs and which FECs it should generate.\n\n         When the value of this object is 'system', LDP will distribute label\n         bindings only for the router's system IP address\n\n         When the value of this object is 'interface', LDP will distribute\n         label bindings for all LDP interfaces\n\n         When the value of this object is 'all', LDP will distribute label\n         bindings for all prefixes in the routing table\n\n         When the value of this object is 'none', LDP will not distribute any\n         label bindings.\n\n         This value is only applicable to LDP interfaces and not for targeted\n         sessions.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenLoopDetectCapable = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 17), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5))).clone(namedValues=NamedValues(("none", 1), ("other", 2), ("hopCount", 3), ("pathVector", 4), ("hopCountAndPathVector", 5))).clone('none')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenLoopDetectCapable.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenLoopDetectCapable.setDescription("The value of vRtrLdpGenLoopDetectCapable indicate whether this LSR\n         supports loop detection and if so, what type of loop detection is\n         supported.\n\n         When the value is 'none' loop detection is not supported on this LSR.\n\n         When the value is 'other' Loop Detection is supported but by a method\n         other than those listed below.\n\n         When the value is 'hopCount' Loop Detection is supported by Hop Count\n         only.\n\n         When the value is 'pathVector' Loop Detection is supported by Path\n         Vector only.\n\n         When the value is 'hopCountAndPathVector' Loop Detection is supported\n         by both Hop Count and Path Vector.\n\n         Since Loop Detection is determined during Session Initialization, an\n         individual session may not be running with loop detection. This object\n         simply gives an indication of whether or not the LSR has the ability\n         to support Loop Detection and which types.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenHopLimit = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 18), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 255)).clone(255)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenHopLimit.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenHopLimit.setDescription("The value of vRtrLdpGenHopLimit specifies the maximum\n         allowable value for the hop count.  The value of this object\n         is valid and used only if vRtrLdpGenLoopDetectCapable has\n         a value of either 'hopCount' or 'hopCountAndPathVector'.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenPathVectorLimit = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 19), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 255)).clone(255)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenPathVectorLimit.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenPathVectorLimit.setDescription("The value of vRtrLdpGenPathVectorLimit specifies the maximum\n         allowable value for the path vector count.  The value of this\n         object is valid and used only if vRtrLdpGenLoopDetectCapable\n         has a value of either 'pathVector' or 'hopCountAndPathVector'.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenBackoffTime = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 20), TmnxLdpBackoffTime().subtype(subtypeSpec=ValueRangeConstraint(1, 2592000)).clone(15)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenBackoffTime.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenBackoffTime.setDescription('The value of vRtrLdpGenBackoffTime specifies the initial value for the\n         backoff interval.\n\n         The backoff interval is the time, in seconds, that LDP waits after an\n         LDP session setup has failed before it attempts to setup the session\n         again. After the LDP session startup fails the first time, the backoff\n         interval is set to the value of vRtrLdpGenBackoffTime. Thereafter, if\n         session startup fails again the backoff interval increases\n         exponentially.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenMaxBackoffTime = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 21), TmnxLdpBackoffTime().clone(120)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenMaxBackoffTime.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenMaxBackoffTime.setDescription('The value of vRtrLdpGenMaxBackoffTime specifies the maximum value for\n         the backoff interval.\n\n         For each successive failure of the LDP session startup, the backoff\n         interval (the time for which the router waits before retrying)\n         increases exponentially. If the backoff interval exceeds\n         vRtrLdpGenMaxBackoffTime, the router will give up trying to establish\n         the LDP session.\n\n         If vRtrLdpGenMaxBackoffTime is set to zero (0), then the backoff\n         interval does not increase exponentially after the first session\n         startup attempt fails. Instead it remains constant and LDP will keep\n         retrying to establish a session until it succeeds.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenTargKeepAliveFactor = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 22), TmnxLdpKeepAliveFactor().clone(4)).setMaxAccess("readcreate")
