if mibBuilder.loadTexts: vRtrLdpGenTargHelloTimeout.setDescription('The value of vRtrLdpGenTargHelloTimeout specifies the hello time also\n         known as hold time. It is the time interval, in seconds, that LDP\n         waits before declaring a neighbor to be down. Hello timeout is local\n         to the system and is sent in the hello messages to a neighbor. Hello\n         timeout cannot be set to a value that is less than 3 times the hello\n         time.\n\n         This value is only applicable to targeted sessions and not to LDP\n         interfaces.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenTargPassiveMode = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 26), TruthValue().clone('false')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenTargPassiveMode.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenTargPassiveMode.setDescription("The value of vRtrLdpGenTargPassiveMode specifies the mode used for\n         setting up LDP sessions. When it has a value of 'true', LDP responds\n         only when it gets a connect request from a peer and will not attempt\n         to actively connect to its neighbors. When it has a value of 'false',\n         LDP actively tries to connect to its peers.\n\n         This value is only applicable to targeted sessions and not to LDP\n         interfaces.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenTargetedSessions = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 27), TruthValue().clone('true')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenTargetedSessions.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenTargetedSessions.setDescription("The value of vRtrLdpGenTargetedSessions specifies whether or\n         not targeted sessions are allowed.  Targeted sessions are LDP\n         sessions between indirectly connected peers.  The discovery\n         messages for an indirect LDP session are addressed to the\n         specified peer instead of to the multicast address.  When this\n         object has a value of 'true', targeted sessions are enabled.\n         When its value is 'false', targeted sessions are disabled.\n\n         This object was obsoleted in release 13.0.")
