if mibBuilder.loadTexts: vRtrLdpGenCreateTime.setDescription('The value of vRtrLdpGenCreateTime specifies the sysUpTime when this\n         LDP instance was created.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpGenUpTime = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 29), TimeInterval()).setMaxAccess("readonly")
if mibBuilder.loadTexts: vRtrLdpGenUpTime.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenUpTime.setDescription("The value of vRtrLdpGenUpTime specifies the time, in hundreds of\n         seconds, that the LDP instance has been in current operational state\n         (vRtrLdpGenOperState).\n\n         If the value of vRtrLdpGenOperState is 'inService (2)', then\n         vRtrLdpGenUpTime specifies the time that the LDP instance has been\n         operationally up.\n\n         If the value of vRtrLdpGenOperState is 'outOfService (3)', then\n         vRtrLdpGenUpTime specifies the time that the LDP instance has been\n         operationally down.\n\n         If the value of vRtrLdpGenOperState is 'transition (4)', then\n         vRtrLdpGenUpTime specifies the time that the LDP instance has been\n         operationally in transition.\n\n         This object was obsoleted in release 13.0.")
