vRtrLdpGenGRNbrLiveTime = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 44), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(5, 300)).clone(120)).setUnits('seconds').setMaxAccess("readcreate")
