if mibBuilder.loadTexts: vRtrLdpGenGRNbrLiveTime.setDescription("The value of vRtrLdpGenGRNbrLiveTime specifies the value for neighbor\n         liveness timer.  The amount of time the Label Switching Router (LSR)\n         keeps its stale label-FEC bindings is set to the lesser of the FT\n         Reconnect Timeout, as was advertised by the  neighbor, and this local\n         timer, called the Neighbor Liveness Timer.\n\n         The LSR waits for the specified time till a LDP session re-establishes\n         itself.  If within that time the LSR still does not establish an LDP\n         session with the neighbor, all the stale bindings are deleted.  This\n         object has meaning only when vRtrLdpGenGracefulRestart is 'true'.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenGRMaxRecoveryTime = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 45), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(15, 1800)).clone(120)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpGenGRMaxRecoveryTime.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpGenGRMaxRecoveryTime.setDescription("The value of vRtrLdpGenGRMaxRecoveryTime specifies the local maximum\n         recovery time.\n\n         If the Label Switching Router (LSR)  determines that the neighbor was\n         able to preserve its MPLS forwarding state (as was indicated by the\n         non-zero Recovery Time advertised by the neighbor), the LSR should\n         further keep the stale label-FEC  bindings, received from the\n         neighbor, for as long as the lesser of the Recovery Time advertised\n         by the neighbor, and a local configurable value, called Maximum\n         Recovery Time, allows.  This object has meaning only when\n         vRtrLdpGenGracefulRestart is 'true'.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpGenLabelWithdrawalDelay = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 1, 1, 46), Unsigned32().subtype(subtypeSpec=ConstraintsUnion(ValueRangeConstraint(0, 0), ValueRangeConstraint(3, 120), )).clone(0)).setUnits('seconds').setMaxAccess("readcreate")
