if mibBuilder.loadTexts: vRtrLdpPolicyType.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpPolicyType.setDescription("The value of vRtrLdpPolicyType indicates the type of policy specified\n         in this row entry.\n\n         When vRtrLdpPolicyType has a value of 'import' this row entry\n         represents the policy filter to be applied to the label binding\n         received from a neighbor.\n\n         When the value is 'export', this row entry represents the policy\n         filter to determine the labels to be advertised to the neighbors.\n\n         When the value is 'ingress', this row entry represents the\n         policy filter to control the route prefixes that are advertised\n         by LDP to the route table.  LDP will advertise label bindings\n         of prefixes that are advertised into it.\n\n         When the value is 'egress', this row entry represents the\n         policy filter to control the route prefixes that are advertised\n         into LDP from the route table.  LDP will advertise label bindings\n         of prefixes that are advertised into it.\n\n         This object is obsoleted in release 2.1.")
vRtrLdpPolicyIndex = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 3, 1, 2), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(1, 5))).setMaxAccess("notaccessible")
