vRtrLdpIfEntry = MibTableRow((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1), ).setMaxAccess("notaccessible").setIndexNames((0, "TIMETRA-VRTR-MIB", "vRtrID"), (0, "TIMETRA-LDP-MIB", "vRtrLdpIfIndex"), (0, "TIMETRA-LDP-MIB", "vRtrLdpPeerAddress"))
if mibBuilder.loadTexts: vRtrLdpIfEntry.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfEntry.setDescription("Each row entry represents an interface on this virtual router that\n         participates in the LDP protocol.\n\n         Row entries can be created or deleted via SNMP SET requests. A row\n         with default attribute values is created by setting vRtrLdpIfRowStatus\n         to 'createAndGo'. A row entry can be destroyed by setting\n         vRtrLdpIfRowStatus to 'destroy'.")
vRtrLdpIfIndex = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 1), InterfaceIndexOrZero()).setMaxAccess("notaccessible")
if mibBuilder.loadTexts: vRtrLdpIfIndex.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfIndex.setDescription('vRtrLdpIfIndex is an index for the row entry and is used mutually\n         exclusively with the vRtrLdpPeerAddress field. If the\n         vRtrLdpPeerAddress field is 0.0.0.0, then vRtrLdpIfIndex is the index\n         for the interface on the virtual router and must be non-zero.\n         Otherwise, vRtrLdpPeerAddress refers to a targeted peer and its\n         vRtrLdpIfIndex is 0.\n\n         This object was obsoleted in release 13.0.')
