vRtrLdpIfInheritance = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 7), Unsigned32().clone(0)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpIfInheritance.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfInheritance.setDescription("Some writable object in this row that can be configured to inherit its\n         value from its corresponding object in the vRtrLdpGeneralTable for LDP\n         interfaces or from the corresponding object in the vRtrLdpIfTable for\n         targeted peers. vRtrLdpIfInheritance controls whether to inherit the\n         operational value of that object, or use the administratively set\n         value.\n\n         Non mask bits will always have value of zero, and any attempt to\n         change the value will be silently discarded.\n\n         This object is a bit-mask, with the following positions:\n         vRtrLdpIfKeepAliveFactor       0x1\n         vRtrLdpIfKeepAliveTimeout      0x2\n         vRtrLdpIfHelloFactor           0x4\n         vRtrLdpIfHelloTimeout          0x8\n         vRtrLdpIfBackoffTime           0x10\n         vRtrLdpIfMaxBackoffTime        0x20\n         vRtrLdpIfTransportAddrType     0x40\n         vRtrLdpIfPassiveMode           0x80\n         vRtrLdpIfHelloReduction        0x100\n         vRtrLdpIfHelloReductionFactor    0x200\n\n         When the bit for an object has value of one, then the object's\n         administrative and operational value are whatever the DEFVAL or most\n         recently SET value. The mask bit(s) will be set to one when set is\n         performed on the inherited object(s). Any attempt to set the mask bit\n         to one will be silently discarded.\n\n         When the bit for an object is set to zero, then the object's\n         administrative and operational value are inherited from the\n         corresponding object in vRtrLdpGeneralTable for LDP interfaces or the\n         vRtrLdpIfTable for targeted peers.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpIfKeepAliveFactor = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 8), TmnxLdpKeepAliveFactor().clone(3)).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpIfKeepAliveFactor.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfKeepAliveFactor.setDescription('The value of vRtrLdpIfKeepAliveFactor specifies the value by which the\n         keepalive timeout (vRtrLdpIfKeepAliveTimeout) should be divided to\n         give the keepalive time i.e. the time interval, in seconds, between\n         LDP keepalive messages. LDP keepalive messages are sent to keep the\n         LDP session from timing out when no other LDP traffic is being sent\n         between the neighbors.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpIfKeepAliveTimeout = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 9), TmnxLdpNewKeepAliveTimeout().clone(30)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpIfKeepAliveTimeout.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfKeepAliveTimeout.setDescription('The value of vRtrLdpIfKeepAliveTimeout specifies the time interval, in\n         seconds, that LDP waits before tearing down a session. If no LDP\n         messages are exchanged during this time interval, the LDP session is\n         torn down. Generally the value of vRtrLdpIfKeepAliveTimeout is\n         configured to be 3 times the keepalive time (the time interval between\n         successive LDP keepalive messages).\n\n         This object was obsoleted in release 13.0.')
vRtrLdpIfHelloFactor = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 10), TmnxLdpHelloFactor().clone(3)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpIfHelloFactor.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfHelloFactor.setDescription('The value of vRtrLdpIfHelloFactor specifies the value by which the\n         hello timeout (vRtrLdpIfHelloTimeout) should be divided to give the\n         hello time i.e. the time interval, in seconds, between LDP Hello\n         messages. LDP uses hello messages to discover neighbors and to detect\n         loss of connectivity with its neighbors.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpIfHelloTimeout = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 11), TmnxLdpNewHelloTimeout().clone(15)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpIfHelloTimeout.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfHelloTimeout.setDescription('The value of vRtrLdpIfHelloTimeout specifies the hello time also known\n         as hold time. It is the time interval, in seconds, that LDP waits\n         before declaring a neighbor to be down. Hello timeout is local to the\n         system and is sent in the hello messages to a neighbor. Hello timeout\n         cannot be set to a value that is less than 3 times the hello time.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpIfBackoffTime = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 12), TmnxLdpBackoffTime().subtype(subtypeSpec=ValueRangeConstraint(1, 2592000)).clone(15)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpIfBackoffTime.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfBackoffTime.setDescription('The value of vRtrLdpIfBackoffTime specifies the initial value for the\n         backoff interval.\n\n         The backoff interval is the time, in seconds, that LDP waits after an\n         LDP session setup has failed before it attempts to setup the session\n         again. After the LDP session startup fails the first time, the backoff\n         interval is set to the value of vRtrLdpIfBackoffTime. Thereafter, if\n         session startup fails again the backoff interval increases\n         exponentially.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpIfMaxBackoffTime = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 13), TmnxLdpBackoffTime().clone(120)).setUnits('seconds').setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpIfMaxBackoffTime.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfMaxBackoffTime.setDescription('The value of vRtrLdpIfMaxBackoffTime specifies the maximum value for\n         the backoff interval.\n\n         For each successive failure of the LDP session startup, the backoff\n         interval (the time for which the router waits before retrying)\n         increases exponentially. If the backoff interval exceeds\n         vRtrLdpIfMaxBackoffTime, the router will give up trying to establish\n         the LDP session.\n\n         If vRtrLdpIfMaxBackoffTime is set to zero (0), then the backoff\n         interval does not increase exponentially after the first session\n         startup attempt fails. Instead it remains constant and LDP will keep\n         retrying to establish a session until it succeeds.\n\n         This object was obsoleted in release 13.0.')
vRtrLdpIfTransportAddrType = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 14), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("interface", 1), ("system", 2))).clone('system')).setMaxAccess("readcreate")
if mibBuilder.loadTexts: vRtrLdpIfTransportAddrType.setStatus('obsolete')
if mibBuilder.loadTexts: vRtrLdpIfTransportAddrType.setDescription("The value of vRtrLdpIfTransportAddrType specifies the source of the\n         transport address to be used when setting up the LDP TCP sessions.\n         This value is meaningful only in case of LDP interfaces and not for\n         targeted peers.\n\n         When the value of this object is 'interface', the interface's IP\n         address is used to setup the LDP session between neighbors. If\n         multiple interfaces exist between two neighbors, the 'interface' mode\n         cannot be used since only one LDP session is actually set up between\n         the two neighbors.\n\n         When the value of this object is 'system', the system's IP address is\n         used to set up the LDP session between neighbors.\n\n         This object was obsoleted in release 13.0.")
vRtrLdpIfPassiveMode = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 8, 5, 1, 15), TruthValue().clone('false')).setMaxAccess("readcreate")
